import json
from datetime import datetime, timezone
from dataclasses import dataclass
from typing import Optional
from agents import function_tool as tool
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError
from google.oauth2.credentials import Credentials
_creds = Credentials.from_authorized_user_file('token.json')
_service = build('calendar', 'v3', credentials=_creds)

@dataclass
class MoveResult:
    moved: bool
    event_id: str
    source_calendar_id: str
    destination_calendar_id: str
    summary: Optional[str] = None
    html_link: Optional[str] = None
    error: Optional[str] = None

def _record_move(event_id: str, source_calendar_id: str, destination_calendar_id: str, summary: Optional[str]) -> None:
    entry = {
        'timestamp': datetime.now(timezone.utc).isoformat(),
        'event_id': event_id,
        'source_calendar_id': source_calendar_id,
        'destination_calendar_id': destination_calendar_id,
        'summary': summary,
    }
    with open('event_move_log.jsonl', 'a') as fh:
        fh.write(json.dumps(entry) + '\n')

@tool
def move_event_to_calendar(event_id: str, source_calendar_id: str, destination_calendar_id: str) -> MoveResult:
    if source_calendar_id == destination_calendar_id:
        return MoveResult(moved=False, event_id=event_id, source_calendar_id=source_calendar_id, destination_calendar_id=destination_calendar_id, error='source and destination are the same')
    try:
        event = _service.events().move(calendarId=source_calendar_id, eventId=event_id, destination=destination_calendar_id).execute()
    except HttpError as exc:
        return MoveResult(moved=False, event_id=event_id, source_calendar_id=source_calendar_id, destination_calendar_id=destination_calendar_id, error=str(exc))
    _record_move(event['id'], source_calendar_id, destination_calendar_id, event.get('summary'))
    return MoveResult(moved=True, event_id=event['id'], source_calendar_id=source_calendar_id, destination_calendar_id=destination_calendar_id, summary=event.get('summary'), html_link=event.get('htmlLink'))
